/**
 * The places in a window that plugins can add to, and the application's own nodes in
 * each menu, in the order they are shown.
 *
 * Generated by `cargo xtask api` from the places of the plugin crate. Do not edit:
 * change the places and generate again.
 */

/** What one of the application's own nodes is. */
export type BuiltinKind = "section" | "item" | "submenu";

/** One of the application's own nodes. */
export interface BuiltinNode {
  readonly key: string;
  readonly kind: BuiltinKind;
  readonly children: readonly BuiltinNode[];
  /** The menu a submenu opens, where it is a menu of its own. */
  readonly opens?: string;
}

/** The menus plugins can add to. */
export const MENUS = [
  "menu.app",
  "menu.app.lume",
  "menu.app.view",
  "menu.app.help",
  "menu.new-tab",
  "menu.tab",
  "menu.pane",
  "menu.status",
] as const;

/** Where status items go. */
export const STATUS_SLOTS = [
  "topbar.left",
  "topbar.center",
  "topbar.right",
  "pane.header",
] as const;

/** The places a plugin's motion can play in. */
export const MOTION_SLOTS = [
  "tab.highlight",
  "menu.enter",
  "toast.enter",
  "toast.exit",
  "palette.enter",
  "panel.enter",
  "float.enter",
  "pill.enter",
  "status.change",
] as const;

/** The dock areas a plugin's panel can open in. */
export const DOCK_AREAS = [
  "left",
  "right",
  "bottom",
] as const;

